/**
 * Stray Playground Pages — SessionStart Hook (#3727)
 *
 * Names untracked, un-ignored playground pages that have been sitting in the
 * working tree for longer than a threshold, so the next session can commit or
 * delete them instead of walking past them.
 *
 * Why this exists: the glyph skill writes explainer pages under
 * `docs/playgrounds/<category>/` and never stages them; `.gitignore` ignores
 * `playgrounds/` globally but un-ignores `docs/playgrounds/`, so the pages are
 * untracked AND un-ignored; and the CI playground gate treats both
 * `docs/playgrounds/` and `docs/<type>--<slug>/` as INERT, so no gate ever
 * sees them. Three pages were found by hand and landed in #3811, two more the
 * same afternoon (#3706 recurred). Nothing looked.
 *
 * Why SessionStart and not Stop: a page the session just wrote is minutes old
 * at Stop, so any age threshold there is either zero (fires on every page,
 * including ones about to be committed) or meaningless. A page still untracked
 * an hour later, seen by the NEXT session, is the forgotten one. This mirrors
 * `lifecycle/sweep-stale-worktrees` (SessionStart, async, age-thresholded).
 *
 * Scope: `docs/playgrounds/**` and `docs/<type>--<slug>/**`, untracked (`??`)
 * only. Tracked, ignored, and out-of-scope files are never reported.
 *
 * Once per session: `.claude/state/stray-playgrounds-<sid>.json` is written
 * after the first report and checked first, so a resume / clear / compact
 * re-fire of SessionStart does not repeat it. Markers older than 7 days are
 * unlinked opportunistically.
 *
 * Opt-outs: `ORK_NO_STRAY_PLAYGROUND_CHECK=1` skips entirely;
 * `ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS=<n>` changes the threshold (default 1).
 *
 * Advisory only: `additionalContext` on SessionStart, never a block.
 *
 * Hook event: SessionStart (async, timeout: 5s)
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, unlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, outputSessionStartContext } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { safeIdentifier } from '../lib/safe-fs.js';

const HOOK_NAME = 'stray-playground-pages';
const DEFAULT_MIN_AGE_HOURS = 1;
const MARKER_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;
const MAX_LISTED = 10;
/** Untracked paths inside these roots are the target set. */
const SCOPE_RE = /^docs\/(playgrounds\/|[^/]*--[^/]*\/)/;

export interface StrayPage {
  path: string;
  ageHours: number;
}

function minAgeMs(): number {
  const raw = process.env.ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS;
  const parsed = raw === undefined ? NaN : Number.parseFloat(raw);
  const hours = Number.isFinite(parsed) && parsed >= 0 ? parsed : DEFAULT_MIN_AGE_HOURS;
  return hours * 60 * 60 * 1000;
}

/**
 * Untracked, un-ignored files under the two playground roots, as repo-relative
 * paths. `null` when git could not answer (no repo, no binary, timeout): the
 * hook then stays silent rather than guessing.
 */
function listUntrackedPages(projectDir: string, ctx: HookContext): string[] | null {
  let out: string;
  try {
    out = execFileSync(
      'git',
      ['--no-optional-locks', 'status', '--porcelain=v1', '--untracked-files=all', '-z', '--', 'docs/playgrounds', 'docs/*--*'],
      { cwd: projectDir, encoding: 'utf8', timeout: 3000, stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true },
    );
  } catch (err) {
    ctx.log(HOOK_NAME, `git status unavailable: ${(err as Error).message}`);
    return null;
  }
  const pages: string[] = [];
  for (const entry of out.split('\0')) {
    if (!entry.startsWith('?? ')) continue;
    const rel = entry.slice(3);
    if (SCOPE_RE.test(rel)) pages.push(rel);
  }
  return pages;
}

function filterByAge(projectDir: string, paths: string[], minAge: number, now: number): StrayPage[] {
  const out: StrayPage[] = [];
  for (const rel of paths) {
    let mtime: number;
    try {
      mtime = statSync(join(projectDir, rel)).mtimeMs;
    } catch {
      continue; // gone between status and stat
    }
    const age = now - mtime;
    if (age >= minAge) out.push({ path: rel, ageHours: Math.round(age / 3600000) });
  }
  return out;
}

function markerDir(projectDir: string): string {
  return join(projectDir, '.claude', 'state');
}

function markerPath(projectDir: string, sessionId: string): string {
  return join(markerDir(projectDir), `stray-playgrounds-${safeIdentifier(sessionId, 'unknown-session')}.json`);
}

function alreadyReported(projectDir: string, sessionId: string): boolean {
  return existsSync(markerPath(projectDir, sessionId));
}

function writeMarker(projectDir: string, sessionId: string, pages: StrayPage[], ctx: HookContext): void {
  try {
    const dir = markerDir(projectDir);
    mkdirSync(dir, { recursive: true });
    const p = markerPath(projectDir, sessionId);
    writeFileSync(p, JSON.stringify({ reportedAt: new Date().toISOString(), pages: pages.map((x) => x.path) }, null, 2));
    // read back once: a marker that cannot be read is not state
    JSON.parse(readFileSync(p, 'utf8'));
    sweepOldMarkers(dir);
  } catch (err) {
    ctx.log(HOOK_NAME, `marker write failed: ${(err as Error).message}`);
  }
}

function sweepOldMarkers(dir: string): void {
  const now = Date.now();
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return;
  }
  for (const name of names) {
    if (!name.startsWith('stray-playgrounds-') || !name.endsWith('.json')) continue;
    const p = join(dir, name);
    try {
      if (now - statSync(p).mtimeMs > MARKER_MAX_AGE_MS) unlinkSync(p);
    } catch {
      // best-effort housekeeping
    }
  }
}

function formatReport(pages: StrayPage[]): string {
  const shown = pages.slice(0, MAX_LISTED);
  const lines = [
    `[stray-playground-pages] ${pages.length} untracked playground page${pages.length === 1 ? '' : 's'} left in the working tree (older than the threshold):`,
    ...shown.map((p) => `  ${p.path} (untracked, ${p.ageHours}h)`),
  ];
  if (pages.length > shown.length) lines.push(`  ...and ${pages.length - shown.length} more`);
  lines.push(
    'Resolve each one: commit it on a branch (a Lab page also needs a docs/site/lab-manifest.json entry, then `node docs/site/scripts/generate-lab-data.mjs`), or delete it.',
    'Opt out with ORK_NO_STRAY_PLAYGROUND_CHECK=1; threshold via ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS.',
  );
  return lines.join('\n');
}

/**
 * SessionStart hook: report untracked playground pages older than the threshold, once per session.
 */
export function strayPlaygroundPages(input: HookInput, ctx: HookContext = NOOP_CTX): HookResult {
  if (process.env.ORK_NO_STRAY_PLAYGROUND_CHECK === '1') return outputSilentSuccess();

  const projectDir = input.project_dir || ctx.projectDir;
  const sessionId = input.session_id || ctx.sessionId || '';
  if (!projectDir) return outputSilentSuccess();

  if (sessionId && alreadyReported(projectDir, sessionId)) return outputSilentSuccess();

  const untracked = listUntrackedPages(projectDir, ctx);
  if (!untracked || untracked.length === 0) return outputSilentSuccess();

  const stray = filterByAge(projectDir, untracked, minAgeMs(), Date.now());
  if (stray.length === 0) return outputSilentSuccess();

  if (sessionId) writeMarker(projectDir, sessionId, stray, ctx);
  ctx.log(HOOK_NAME, `${stray.length} stray playground page(s) reported`);
  return outputSessionStartContext(formatReport(stray));
}

export const __internals = { listUntrackedPages, filterByAge, formatReport, markerPath, minAgeMs, SCOPE_RE, DEFAULT_MIN_AGE_HOURS };
